from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text()
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected exactly one patch target, found {count}")
    p.write_text(text.replace(old, new, 1))


replace_once(
    "compiler/process.go",
    '''\t// Web-scrape connector fields (JobType == WebScrapeJobType, ADR-0118). Url (above)\n\t// is the model-authored page to fetch; ScrapeSelector is the CSS selector whose\n\t// matches are extracted (literal-or-FEEL, the zero RestExpr for a non-scrape task);\n\t// ScrapeAttribute is the interned HTML attribute read from each match (-1 → each\n\t// match's text content). ResultVar (above) receives the extracted values as a JSON\n\t// array. Read only by the in-process web-scraping worker.\n\tScrapeSelector  RestExpr\n\tScrapeAttribute int32\n''',
    '''\t// Web-scrape connector fields (JobType == WebScrapeJobType, ADR-0118/0190).\n\t// Url (above) is the model-authored document to fetch. HTML uses ScrapeSelector\n\t// (literal-or-FEEL) and optional ScrapeAttribute. ScrapeFormat is compiled from\n\t// format=html|rss|atom; its zero value is HTML so models compiled before ADR-0190\n\t// keep their semantics. ScrapeMaxItems is the deterministic first-N bound (0 =\n\t// unlimited). Feed modes return structured entries and never inspect selector or\n\t// attribute at runtime.\n\tScrapeSelector  RestExpr\n\tScrapeAttribute int32\n\tScrapeFormat    WebScrapeFormat\n\tScrapeMaxItems  int32\n''',
)

replace_once(
    "compiler/parse.go",
    '''// A web-scraping connector task's parameters, carried on a service task as an\n// <atlas:webscrapeConnector url="..." selector="..." attribute="..."\n// resultVariable="..."/> extension element (ADR-0118). url (required) is the page to\n// fetch and selector (required) the CSS selector whose matches are extracted; both\n// live in the model (unlike a registry endpoint), and credentials never do. attribute,\n// when set, names the HTML attribute read from each match (omit to read each match's\n// text). resultVariable (required) receives the extracted values as a JSON array. url\n// and selector are literal or, with a leading '=', a FEEL expression over the instance's\n// variables at call time (the fx toggle, ADR-0067); attribute is a structural literal.\ntype xmlWebScrapeConnector struct {\n\tUrl            string `xml:"url,attr"`\n\tSelector       string `xml:"selector,attr"`\n\tAttribute      string `xml:"attribute,attr"`\n\tResultVariable string `xml:"resultVariable,attr"`\n\tRetries        string `xml:"retries,attr"`\n}\n''',
    '''// A web-scraping connector task's parameters, carried on a service task as an\n// <atlas:webscrapeConnector> extension (ADR-0118/0190). url and resultVariable are\n// always required. format is a structural literal (html by default, rss, or atom);\n// maxItems is an optional non-negative structural bound. HTML requires selector and\n// may name attribute; RSS/Atom prohibit both. url and the HTML selector may be\n// literal-or-FEEL; format, maxItems, and attribute are compiled structure.\ntype xmlWebScrapeConnector struct {\n\tUrl            string `xml:"url,attr"`\n\tSelector       string `xml:"selector,attr"`\n\tAttribute      string `xml:"attribute,attr"`\n\tFormat         string `xml:"format,attr"`\n\tMaxItems       string `xml:"maxItems,attr"`\n\tResultVariable string `xml:"resultVariable,attr"`\n\tRetries        string `xml:"retries,attr"`\n}\n''',
)

replace_once(
    "compiler/connector_compile.go",
    '''// compileWebScrapeConnectorTask compiles an <atlas:webscrapeConnector> task: it\n// fetches the model-authored URL and extracts the elements matching a CSS selector\n// via the job path (ADR-0118), not an external service-task worker. The URL and\n// selector live in the model (like REST's endpoint, ADR-0067); the extracted values\n// are written back into the required result variable as a JSON array.\nfunc compileWebScrapeConnectorTask(b *Builder, st xmlServiceTask, retries int32) (int32, error) {\n\tcn := st.WebScrape\n\tif strings.TrimSpace(cn.Url) == "" {\n\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q needs a url", st.Id)\n\t}\n\tif strings.TrimSpace(cn.Selector) == "" {\n\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q needs a selector", st.Id)\n\t}\n\tif strings.TrimSpace(cn.ResultVariable) == "" {\n\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q needs a resultVariable", st.Id)\n\t}\n\turl, err := restValue(st.Id, "url", cn.Url)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tselector, err := restValue(st.Id, "selector", cn.Selector)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\treturn b.AddWebScrapeConnectorTask(WebScrapeConfig{\n\t\tUrl:       url,\n\t\tSelector:  selector,\n\t\tAttribute: strings.TrimSpace(cn.Attribute),\n\t\tResult:    strings.TrimSpace(cn.ResultVariable),\n\t\tRetries:   retries,\n\t}), nil\n}\n''',
    '''// compileWebScrapeConnectorTask compiles an <atlas:webscrapeConnector> task.\n// HTML preserves ADR-0118's selector-to-string-array behavior. ADR-0190 adds RSS\n// and Atom as explicit deploy-time formats whose worker output is a structured feed\n// array. No response inspection chooses the mode at runtime (I5).\nfunc compileWebScrapeConnectorTask(b *Builder, st xmlServiceTask, retries int32) (int32, error) {\n\tcn := st.WebScrape\n\tif strings.TrimSpace(cn.Url) == "" {\n\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q needs a url", st.Id)\n\t}\n\tif strings.TrimSpace(cn.ResultVariable) == "" {\n\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q needs a resultVariable", st.Id)\n\t}\n\tformat, err := webScrapeFormat(st.Id, cn.Format)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tmaxItems, err := webScrapeMaxItems(st.Id, cn.MaxItems)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\thasSelector := strings.TrimSpace(cn.Selector) != ""\n\thasAttribute := strings.TrimSpace(cn.Attribute) != ""\n\tswitch format {\n\tcase WebScrapeFormatHTML:\n\t\tif !hasSelector {\n\t\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q needs a selector for html format", st.Id)\n\t\t}\n\tcase WebScrapeFormatRSS, WebScrapeFormatAtom:\n\t\tif hasSelector {\n\t\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q format %q does not use a selector", st.Id, format.String())\n\t\t}\n\t\tif hasAttribute {\n\t\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q format %q does not use an attribute", st.Id, format.String())\n\t\t}\n\t}\n\turl, err := restValue(st.Id, "url", cn.Url)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tvar selector RestExpr\n\tif format == WebScrapeFormatHTML {\n\t\tselector, err = restValue(st.Id, "selector", cn.Selector)\n\t\tif err != nil {\n\t\t\treturn 0, err\n\t\t}\n\t}\n\treturn b.AddWebScrapeExtractionTask(WebScrapeExtractionConfig{\n\t\tUrl:       url,\n\t\tSelector:  selector,\n\t\tAttribute: strings.TrimSpace(cn.Attribute),\n\t\tFormat:    format,\n\t\tMaxItems:  maxItems,\n\t\tResult:    strings.TrimSpace(cn.ResultVariable),\n\t\tRetries:   retries,\n\t}), nil\n}\n\nfunc webScrapeFormat(taskID, raw string) (WebScrapeFormat, error) {\n\tswitch strings.ToLower(strings.TrimSpace(raw)) {\n\tcase "", "html":\n\t\treturn WebScrapeFormatHTML, nil\n\tcase "rss":\n\t\treturn WebScrapeFormatRSS, nil\n\tcase "atom":\n\t\treturn WebScrapeFormatAtom, nil\n\tdefault:\n\t\treturn WebScrapeFormatHTML, fmt.Errorf("compiler: webscrape connector task %q has an unknown format %q (want html, rss, or atom)", taskID, raw)\n\t}\n}\n\nfunc webScrapeMaxItems(taskID, raw string) (int32, error) {\n\traw = strings.TrimSpace(raw)\n\tif raw == "" {\n\t\treturn 0, nil\n\t}\n\tn, err := strconv.Atoi(raw)\n\tif err != nil {\n\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q has a non-numeric maxItems %q", taskID, raw)\n\t}\n\tif n < 0 {\n\t\treturn 0, fmt.Errorf("compiler: webscrape connector task %q has a negative maxItems %d", taskID, n)\n\t}\n\treturn int32(n), nil\n}\n''',
)
